--- Observation ---
  ---- Generic resource index for most of searches
  CREATE INDEX IF NOT EXISTS observation_resource_idx ON Observation USING GIN (resource jsonb_path_ops);

  ---- Observation.date
  CREATE INDEX IF NOT EXISTS observation_date_param_jsonpath_multirange ON public.observation USING gist (
    aidbox_extract_range (
      resource,
      ARRAY[
        '$."effective"."Period"[*]'::jsonpath,
        '$."effective"."dateTime"[*]'::jsonpath,
        '$."effective"."instant"[*]'::jsonpath
      ]
    )
  );

  ---- Observation.value-quantity (top-level valueQuantity)
  CREATE INDEX IF NOT EXISTS observation_value_quantity_max_idx ON observation USING btree (
    (knife_extract_max_numeric(resource, '[["value","Quantity","value"],["value","SampledData"]]'::jsonb))
  );
  CREATE INDEX IF NOT EXISTS observation_value_quantity_min_idx ON observation USING btree (
    (knife_extract_min_numeric(resource, '[["value","Quantity","value"],["value","SampledData"]]'::jsonb))
  );

  CREATE INDEX IF NOT EXISTS observation_value_quantity_min_max_idx ON observation USING btree (
    (knife_extract_min_numeric(resource, '[["value","Quantity","value"],["value","SampledData"]]'::jsonb)),
    (knife_extract_max_numeric(resource, '[["value","Quantity","value"],["value","SampledData"]]'::jsonb))
  );

  ---- Observation.component-value-quantity
  CREATE INDEX IF NOT EXISTS observation_component_value_quantity_max_idx ON observation USING btree (
    (knife_extract_max_numeric(resource, '[["component","value","Quantity","value"],["component","value","SampledData"]]'::jsonb))
  );
  CREATE INDEX IF NOT EXISTS observation_component_value_quantity_min_idx ON observation USING btree (
    (knife_extract_min_numeric(resource, '[["component","value","Quantity","value"],["component","value","SampledData"]]'::jsonb))
  );

  CREATE INDEX IF NOT EXISTS observation_component_value_quantity_composite_max_idx ON observation USING btree (
    (jsonpath_extract_max_numeric ( resource, '$."component"."value"."Quantity"[*]."value"') )
  );

  CREATE INDEX observation_component_quantity_value_composite_min_idx_pt ON public.observation USING btree (
    (jsonpath_extract_min_numeric ( resource, '$."value"."Quantity"[*]."value"'))
  ) where (resource @> '{"code": {"coding": [{"code": "8867-4"}]}}');

  CREATE INDEX observation_component_quantity_value_composite_max_idx_pt ON public.observation USING btree (
    (jsonpath_extract_max_numeric ( resource, '$."value"."Quantity"[*]."value"'))
  ) where (resource @> '{"code": {"coding": [{"code": "8867-4"}]}}');


  ---- Observation.combo-value-quantity (top-level OR component)
  CREATE INDEX IF NOT EXISTS observation_combo_value_quantity_max_idx ON observation USING btree (
    (knife_extract_max_numeric(resource, '[["value","Quantity","value"],["value","SampledData"],["component","value","Quantity","value"],["component","value","SampledData"]]'::jsonb))
  );
  CREATE INDEX IF NOT EXISTS observation_combo_value_quantity_min_idx ON observation USING btree (
    (knife_extract_min_numeric(resource, '[["value","Quantity","value"],["value","SampledData"],["component","value","Quantity","value"],["component","value","SampledData"]]'::jsonb))
  );
